css:
.action-banner a[href*="frappe.utils.print_format.download_pdf"] {
    display: none !important;
}

.print-format td, .print-format th {
    padding: 0px !important;
    vertical-align: middle !important;
} 

/* General styling for tables */
table {
    border-collapse: collapse;
    /*table-layout: ;*/
    width: 100%;
    /*font-size: 10pt;*/
    font-family: Arial;
    /*text-align: center;*/
    /*margin-left: 20px;*/
    /*margin-right: 20px;*/
}

.logo-container {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: center;
  margin-top: 20px;
  margin-bottom: 20px;
  /*border: red 1px solid;*/
}


@media print {
    table {
        table-layout: fixed;
        width: 100%;
        border-collapse: collapse;
    }
    th, td {
        font-size: 8pt;
        /*text-align: center;*/
        /*white-space: nowrap;*/
        /*overflow: hidden;*/
        text-overflow: ellipsis;
    }

}
img {
  /*max-width: 100%;*/
  height: 70px;
  /*width:140px;*/
  margin-right: 20px;
  margin-left: 20px;
  /*border: red 1px solid;*/
}

html:
{% set employees = frappe.get_all(
    "Employee",
    filters={"employee": doc.employee},
    fields=["employee", "company", "custom_name_extension", "last_name", "first_name", "middle_name", "custom_full_maiden_name", "custom_place_of_birth", "date_of_birth"]) 
%}
{% set hr_director = frappe.get_all("Employee", filters={"designation": "DIRECTOR (Human Resource Development Office)"}, fields=["salutation", "first_name", "middle_name", "last_name", "custom_name_extension", "designation"]) | list %}
{% set hr_oic = frappe.get_all("Employee", filters={"designation": "OIC (Human Resource Development Office)"}, fields=["salutation", "first_name", "middle_name", "last_name", "custom_name_extension", "designation"]) | list %}
{% set excluded_status_appointment = ["Part Time/Job Order", "Contract of Service"] %}
{% if doc.generate_for_gsis==true %}
    {% set emp_iw_current = frappe.get_all(
        "Employee Internal Work History",
        filters={ "parent": doc.employee, "custom_iw_status_appointment": ["not in", excluded_status_appointment] },
        fields=["custom_is_present_work", "from_date", "to_date", "custom_iw_position", "custom_iw_status_appointment", "custom_monthly_salary", "custom_hourly_salary", "branch", "custom_leave_without_pay", "custom_remarks"],
        order_by="from_date ASC"
    ) %}
{% else %}
    {% set emp_iw_current = frappe.get_all(
        "Employee Internal Work History",
        filters={ "parent": doc.employee },
        fields=["custom_is_present_work", "from_date", "to_date", "custom_iw_position", "custom_iw_status_appointment", "custom_monthly_salary", "custom_hourly_salary", "branch", "custom_leave_without_pay", "custom_remarks"],
        order_by="from_date ASC"
    ) %}
{% endif %}

{% set emp_iw_len = emp_iw_current | length %}

<div class="letter-head">
    <div class="logo-container">
        <div class="image">
            <img src="/assets/cvsu_hris/images/CvSU.png">
        </div>
        <div style="text-align: center;">
            <span style="font-size: 10pt;">Republic of the Philippines</span><br>
            <span style="font-size: 12pt; font-weight: bold;">{{ employees[0].company | upper }}</span><br>
            <span style="font-size: 10pt;">Indang, Cavite</span>
        </div>
        <div class="image">
            <img src="/assets/cvsu_hris/images/Bagong_Pilipinas.png">
        </div>
    </div>

    <pre style="color: black; font-family: Arial; background-color: white; border: 0; text-align: center; font-weight: bold; font-size: 14pt;">S E R V I C E  R E C O R D</pre>
</div>

<table>
    <tr>
        <td>Name:</td>
        <td colspan="2" style="border-bottom: 1pt solid black; font-weight: bold;">{{ employees[0].last_name|upper + ' ' + employees[0].custom_name_extension|upper if employees[0].custom_name_extension else employees[0].last_name|upper}}</td>
        <td colspan="3" style="border-bottom: 1pt solid black; font-weight: bold;">{{ employees[0].first_name | upper if employees[0].first_name }}</td>
        <td colspan="2" style="border-bottom: 1pt solid black; font-weight: bold;">{{ employees[0].middle_name | upper if employees[0].middle_name}}</td>
        <td colspan="1" rowspan="2" style="text-align: justify; font-style: italic; font-size: 9pt; width: 150px;">(If married woman, give also full maiden name)</td>
    </tr>
    <tr>
        <td></td>
        <td colspan="2" style="font-style: italic; font-size: 9pt;">(Surname)</td>
        <td colspan="3" style="font-style: italic; font-size: 9pt;">(Given Name)</td>
        <td colspan="2" style="font-style: italic; font-size: 9pt;">(Middle Name)</td>
    </tr>
    <tr>
        <td colspan="8"></td>
        <td style="font-weight: bold;">{{ employees[0].custom_full_maiden_name if employees[0].custom_full_maiden_name else 'N/A'}}</td>
    </tr>
    <tr>
        <td>Birth:</td>
        <td colspan="4" style="border-bottom: 1pt solid black; font-weight: bold;">{{ frappe.utils.formatdate(employees[0].date_of_birth, "MMMM dd, yyyy") | upper }}</td>
        <td colspan="3" style="border-bottom: 1pt solid black; font-weight: bold;">{{ employees[0].custom_place_of_birth | upper if employees[0].custom_place_of_birth }}</td>
        <td colspan="1" rowspan="3" style="text-align: justify; font-style: italic; font-size: 9pt; width: 150px;">(Data herein should be checked from birth or baptismal certificate or some other reliable document.)</td>
    </tr>
    <tr></tr>
    <tr>
        <td></td>
        <td colspan="4" style="font-style: italic; font-size: 9pt;">(Date)</td>
        <td colspan="3" style="font-style: italic; font-size: 9pt;">(Place)</td>
    </tr>
    <tr>
        <td colspan="9" style="text-align: justify; text-indent: 40px;">This is to certify that the employee named herein above actually rendered services in this Office as shown by the service 
        record below. Each line of which is supported by appointment and other papers actually issued by this Office and approved by the authorities concerned.</td>
    </tr>
</table>

<table border="1" style="border-collapse: collapse;">
    <tr style="border-top: double;">
        <td colspan="2" style="font-weight: bold; text-align: center;">SERVICE</td>
        <td colspan="3" rowspan="2" style="font-weight: bold; text-align: center;">RECORD OF APPOINTMENT</td>
        <td colspan="4" rowspan="2" style="font-weight: bold; text-align: center;">OFFICE/ENTITY/DIVISION</td>
    </tr>
    <tr>
        <td colspan="2" style="font-weight: bold; text-align: center;">Inclusive Dates</td>
    </tr>
    <tr>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">From</td>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">To</td>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">Designation</td>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">Status</td>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">Salary</td>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">Station/Place of Assignment</td>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">Branch</td>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">L/V w/o Pay</td>
        <td style="font-weight: bold; text-align: center; font-size: 9pt;">Remarks</td>
    </tr>

    {% for index in range(emp_iw_len) %}
        <tr>
            <td style="font-size: 8pt; text-align: center; width: 80px;">{{ frappe.utils.formatdate(emp_iw_current[index].from_date, "MM/dd/yyyy") }}</td>
            <td style="font-size: 8pt; text-align: center; width: 80px;">
                {% if emp_iw_current[index].custom_is_present_work == 1 %}
                    to date
                {% else %}
                    {{ frappe.utils.formatdate(emp_iw_current[index].to_date, "MM/dd/yyyy") }}
                {% endif %}
            </td>
    
            <!-- Handle Position Display -->
            <td style="font-size: 8pt; text-align: center; width: 180px;">
                {% set current_position = emp_iw_current[index].custom_iw_position %}
    
                {# Compare with previous position, avoid first iteration #}
                {% if index == 0 %}
                    <p>{{ current_position }}</p>
                {% else %}
                    {% set previous_position = emp_iw_current[index - 1].custom_iw_position %}
                    {% if current_position == previous_position  %}
                        <p>-do-</p>
                    {% else %}
                        {{ current_position }}
                    {% endif %}
                {% endif %}
            </td>
    
            <td style="font-size: 8pt; text-align: center; width: 90px;">
                {% set current_status_appointment = emp_iw_current[index].custom_iw_status_appointment %}
    
                {# Compare with previous position, avoid first iteration #}
                {% if index == 0 %}
                    <p>{{ current_status_appointment }}</p>
                {% else %}
                    {% set previous_status_appointment = emp_iw_current[index - 1].custom_iw_status_appointment %}
                    {% if current_status_appointment == previous_status_appointment  %}
                        <p>-do-</p>
                    {% else %}
                        {{ current_status_appointment }}
                    {% endif %}
                {% endif %}
            </td>

            {% if emp_iw_current[index].custom_iw_status_appointment=='Part Time/Job Order' or emp_iw_current[index].custom_iw_status_appointment=='Contract of Service' %}
                {% if emp_iw_current[index].custom_monthly_salary=='' or emp_iw_current[index].custom_monthly_salary==None %}
                    {% set cleaned_salary = emp_iw_current[index].custom_hourly_salary | replace(',', '') %}
                {% else %}
                    {% set cleaned_salary = emp_iw_current[index].custom_monthly_salary | replace(',', '') %}
                {% endif %}
            {% else %}
                {% set cleaned_salary = emp_iw_current[index].custom_monthly_salary | replace(',', '') %}
            {% endif %}
            {% set first_part = cleaned_salary.split(' ')[0] %}
            {% set first_part = cleaned_salary.split('/')[0] %}
            {% set salary = first_part | float | round(2) %}

            <td style="font-size: 8pt; text-align: center; width: 120px;">
                {% if emp_iw_current[index].custom_iw_status_appointment=='Part Time/Job Order' or emp_iw_current[index].custom_iw_status_appointment=='Contract of Service' %}
                    {% if emp_iw_current[index].custom_monthly_salary=='' or emp_iw_current[index].custom_monthly_salary==None %}
                        {{ "{:,.2f}".format(salary)}}/hr
                    {% else %}
                        {{ "{:,.2f}".format(salary)}}/m
                    {% endif %}
                {% elif emp_iw_current[index].custom_iw_status_appointment=='Permanent' or emp_iw_current[index].custom_iw_status_appointment=='Temporary' or emp_iw_current[index].custom_iw_status_appointment=='Coterminuos' %}
                    {{ "{:,.2f}".format(salary*12)}}/a
                {% elif emp_iw_current[index].custom_iw_status_appointment=='Casual' or emp_iw_current[index].custom_iw_status_appointment=='Contractual' %}
                    {{ "{:,.2f}".format(salary)}}/m
                {% endif %}
            </td>   
            <td style="font-size: 8pt; text-align: center; width: 220px;">
                {% set current_branch = emp_iw_current[index].branch %}
    
                {# Compare with previous position, avoid first iteration #}
                {% if index == 0 %}
                    <p>CvSU-{{ current_branch }}</p>
                {% else %}
                    {% set previous_branch = emp_iw_current[index - 1].branch %}
                    {% if current_branch == previous_branch  %}
                        <p>-do-</p>
                    {% else %}
                        CvSU-{{ current_branch }}
                    {% endif %}
                {% endif %}
            </td>
            <td style="font-size: 8pt; text-align: center; width: 80px;">
                {# Compare with previous position, avoid first iteration #}
                {% if index == 0 %}
                    <p>National</p>
                {% else %}
                    <p>-do-</p>
                {% endif %}
            </td>
            <td style="font-size: 8pt; text-align: center; width: 70px;">
                {% set current_leave_without_pay = emp_iw_current[index].custom_leave_without_pay %}
                {% if current_leave_without_pay == None or current_leave_without_pay == '' %}
                    {% set current_leave_without_pay = None %}
                {% endif %}
                {# Compare with previous position, avoid first iteration #}
                {% if index == 0 %}
                    <p>{{ current_leave_without_pay }}</p>
                {% else %}
                    {% set previous_leave_without_pay = emp_iw_current[index - 1].custom_leave_without_pay %}
                    {% if previous_leave_without_pay == None or previous_leave_without_pay == '' %}
                        {% set previous_leave_without_pay = None %}
                    {% endif %}
                    {% if current_leave_without_pay == previous_leave_without_pay  %}
                        <p>-do-</p>
                    {% else %}
                        {{ current_leave_without_pay }}
                    {% endif %}
                {% endif %}    
            </td>
            <td style="font-size: 8pt; text-align: center; width: 120px;">{{ emp_iw_current[index].custom_remarks if emp_iw_current[index].custom_remarks }}</td>
        </tr>
    {% endfor %}

    <tr>
        <td colspan="9" style="font-weight: bold; text-align: center;">{{ doc.reasons_for_requesting | upper }}</td>
    </tr>
</table>

<table>
    <tr>
        <td colspan="9" style="text-indent: 40px; padding-bottom: 20px;">Issued in compliance with Executive Order No. 54 dated August 10, 1954, and in accordance with Circular No. 58, dated August 10, 1954 of the System.</td>
    </tr>
    <tr>
        <td colspan="9" style="height: 20px;"></td> <!-- Empty row with height -->
    </tr>
    <tr>
        <td colspan="3"></td>
        <td colspan="3" style="width: 300px;"></td>
        <td colspan="3">Certified Correct:</td>
    </tr>
    <tr>
        <td colspan="9" style="height: 20px;"></td> <!-- Adjust the height as needed -->
    </tr>
    <tr>
        <td colspan="3" style="font-weight: bold; border-bottom: 1pt solid black; text-align: center;">
            {{ frappe.utils.formatdate(frappe.utils.nowdate(), "MMMM dd, yyyy") }}
        </td>
        <td colspan="3" style="width: 300px;"></td>
        <td colspan="3" style="font-weight: bold; border-bottom: 1pt solid black; text-align: center;">
            {% if hr_director %}
                {{ hr_director[0].salutation | upper + '. ' if hr_director[0].salutation }} {{ hr_director[0].first_name | upper + ' ' }} {{ hr_director[0].middle_name[0] | upper + '. ' if hr_director[0].middle_name }} {{ hr_director[0].last_name + ' ' + hr_director[0].custom_name_extension if hr_director[0].custom_name_extension else hr_director[0].last_name }}
            {% elif hr_oic %}
                {{ hr_oic[0].salutation | upper + '. ' if hr_oic[0].salutation }} {{ hr_oic[0].first_name | upper + ' ' }} {{ hr_oic[0].middle_name[0] | upper + '. ' if hr_oic[0].middle_name }} {{ hr_oic[0].last_name + ' ' + hr_oic[0].custom_name_extension if hr_oic[0].custom_name_extension else hr_oic[0].last_name }}
            {% endif %}
        </td>
    </tr>
    <tr>
        <td colspan="3" style="text-align: center;">Date</td>
        <td colspan="3" style="width: 300px;"></td>
        <td colspan="3" style="text-align: center;">
            {% if hr_director %}
                Director, HRDO
            {% elif hr_oic %}
                OIC, HRDO
            {% endif %}
        </td>
    </tr>
</table>
